html:
{% set company = frappe.get_doc("Company", doc.company) if doc.company else None %}
{% set company_address_name = frappe.db.get_value("Dynamic Link", {"link_doctype": "Company", "link_name": doc.company, "parenttype": "Address"}, "parent") if doc.company else None %}
{% set company_address = frappe.get_doc("Address", company_address_name) if company_address_name else None %}
{% set customer = frappe.get_doc("Customer", doc.customer) if doc.customer else None %}
{% set customer_address = frappe.get_doc("Address", doc.customer_address) if doc.customer_address and frappe.db.exists("Address", doc.customer_address) else None %}

{% set diagnostico_name = doc.get("custom_diagnostico") %}
{% if not diagnostico_name and doc.get("custom_movimiento_de_equipo") %}
  {% set diagnostico_name = frappe.db.get_value("Diagnostico", {"movimiento_de_equipo": doc.custom_movimiento_de_equipo, "docstatus": ["!=", 2]}, "name", order_by="creation desc") %}
{% endif %}
{% set diagnostico = frappe.get_doc("Diagnostico", diagnostico_name) if diagnostico_name else None %}

{% set movimiento = frappe.get_doc("Movimiento de Equipo", doc.custom_movimiento_de_equipo) if doc.get("custom_movimiento_de_equipo") and frappe.db.exists("Movimiento de Equipo", doc.custom_movimiento_de_equipo) else None %}
{% set work_order_name = frappe.db.get_value("Work Order", {"sales_order": doc.name, "docstatus": ["!=", 2]}, "name", order_by="creation desc") %}
{% set work_order = frappe.get_doc("Work Order", work_order_name) if work_order_name else None %}

{% set equipo_row = movimiento.equipos[0] if movimiento and movimiento.get("equipos") else None %}
{% set equipo = frappe.get_doc("Equipo", equipo_row.equipo) if equipo_row and equipo_row.equipo and frappe.db.exists("Equipo", equipo_row.equipo) else None %}

{% set first_time_log = diagnostico.time_logs[0] if diagnostico and diagnostico.get("time_logs") else None %}
{% set tecnico = frappe.db.get_value("Employee", first_time_log.employee, "employee_name") if first_time_log and first_time_log.employee else "" %}
{% set tax_ratio = (doc.total_taxes_and_charges / doc.net_total) if doc.net_total else 0 %}

{% set ns = namespace(
  materials_without_tax=0,
  materials_with_tax=0,
  services_without_tax=0,
  services_with_tax=0,
  discount_without_tax=0,
  discount_with_tax=0,
  material_rows=0,
  service_rows=0
) %}

<style>
@page {
  size: Letter;
  margin: 5mm;
}

.print-format {
  margin: 0 !important;
  padding: 0 !important;
  font-family: Arial, Helvetica, sans-serif;
  color: #000;
}

.af-page {
  width: 100%;
  font-size: 8px;
  line-height: 1.15;
}

table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

/* Reset defensivo de bordes. Especificidad baja a propósito para
   no pisar reglas mas especificas (.box, .items th, .subtotal,
   .double-line, .firma-border, etc). */
td, th {
  border: none;
}

td, th {
  padding: 1.5px 3px;
  vertical-align: top;
}

.logo {
  width: 150px;
  max-height: 48px;
  object-fit: contain;
}

.title {
  text-align: center;
  color: #000080;
  font-weight: 700;
  font-size: 13px;
  line-height: 1.1;
}

.header-no {
  font-size: 11px;
  font-weight: 700;
  color: #000080;
  line-height: 1.12;
  white-space: nowrap;
}

/* .field-label (antes ".label"): ".label" colisiona con la clase de
   "badge" que Frappe/Bootstrap usa globalmente y causaba recuadros
   no deseados. white-space:nowrap evita que una etiqueta larga se
   parta y se monte sobre la celda de al lado. */
.field-label {
  font-weight: 700;
  white-space: nowrap;
}

.center {
  text-align: center;
}

.right {
  text-align: right;
}

.bold {
  font-weight: 700;
}

.small {
  font-size: 7px;
}

/* ---- Paneles con encabezado, estilo orden de taller ---- */
.box {
  border: 1px solid #000;
}

.box-header {
  background: #000080;
  color: #fff;
  font-weight: 700;
  font-size: 8px;
  letter-spacing: .3px;
  text-transform: uppercase;
  padding: 2px 8px;
}

.box-body {
  padding: 3px 8px;
}

/* ---- Barra de datos del taller / orden ---- */
.info-bar td {
  padding: 3px 6px;
  vertical-align: top;
}

.info-bar .info-col-right {
  border-left: 1px solid #000;
}

.company-name {
  font-size: 8.5px;
  font-weight: 700;
  line-height: 1.3;
}

.company-line {
  font-size: 7.5px;
  line-height: 1.25;
}

.order-line {
  font-size: 7.5px;
  line-height: 1.35;
}

/* ---- Datos cliente / equipo ---- */
.info td {
  height: 10px;
  padding: 1px 3px;
}

.yellow-box {
  background: #fff200;
  font-weight: 700;
  font-size: 8px;
  line-height: 1.25;
  padding: 4px 6px;
}

.items {
  font-size: 7.5px;
}

.items th {
  font-weight: 400;
  color: #34495e;
  border-bottom: 1px solid #000;
  text-align: center;
  padding: 2px 3px;
}

.items td {
  padding: 1.5px 3px;
}

.green-row td {
  background: #92d050;
}

.subtotal td {
  border-top: 1px solid #000;
  font-weight: 700;
  padding-top: 2px;
}

.double-line td {
  border-bottom: 2px double #000;
}

/* ---- Totales ---- */
.totals-box {
  width: 46%;
}

.totals td {
  padding: 2px 4px;
  font-size: 8px;
}

.totals .col-header {
  font-size: 7px;
  color: #34495e;
  border-bottom: 1px solid #000;
  padding-bottom: 2px;
}

.final-total td {
  font-size: 11px;
  font-weight: 700;
  border-top: 1px solid #000;
  padding-top: 3px;
}

.grand-total {
  background: #66d9ff;
  padding: 2px 6px !important;
}

/* ---- Firmas ---- */
.firmas {
  margin-top: 6px;
}

.firma-space td {
  height: 16px;
}

.firma-border td {
  border-top: 1px solid #000;
}

.firma-caption {
  text-align: center;
  font-size: 7.5px;
  font-weight: 700;
  padding-top: 2px;
}

.firma-sub {
  text-align: center;
  font-size: 7px;
  font-weight: 400;
  color: #34495e;
}

.note {
  margin-top: 5px;
  font-size: 7.5px;
  font-weight: 700;
}

.mt-2 { margin-top: 2px; }
.mt-4 { margin-top: 3px; }
.mt-6 { margin-top: 4px; }
.mt-8 { margin-top: 5px; }
.mt-10 { margin-top: 6px; }

.keep-together {
  page-break-inside: avoid;
}
</style>

<div class="af-page">

  <!-- ENCABEZADO -->
  <table>
    <tr>
      <td style="width: 30%;">
        {% if company and company.company_logo %}
          <img class="logo" src="{{ company.company_logo }}">
        {% endif %}
      </td>
      <td style="width: 42%;" class="title">
        DETALLE ORDEN DE TRABAJO No.<br>
        PRE-FACTURA<br>
        <span style="font-size: 10px; color:#000;">FECHA PRE-FACTURA</span>
      </td>
      <td style="width: 28%;">
        <table>
          <tr>
            <td class="header-no">{{ work_order.name if work_order else doc.name }}</td>
          </tr>
          <tr>
            <td class="header-no">{{ doc.get("custom_doc_numero") or doc.name }}</td>
          </tr>
          <tr>
            <td class="header-no" style="color:#000;">{{ frappe.utils.formatdate(doc.transaction_date, "d/MM/yyyy") }}</td>
          </tr>
        </table>
      </td>
    </tr>
  </table>

  <!-- DATOS DEL TALLER Y DE LA ORDEN -->
  <table class="box info-bar mt-6">
    <colgroup>
      <col style="width: 58%;">
      <col style="width: 42%;">
    </colgroup>
    <tr>
      <td>
        <div class="company-name">{{ company.company_name if company else "" }}</div>
        <div class="company-line">NIT: {{ company.tax_id if company and company.tax_id else "" }}</div>
        <div class="company-line">{{ company_address.address_line1 if company_address else "" }}</div>
        <div class="company-line">
          Tel: {{ company_address.phone if company_address and company_address.phone else "" }}
          {% if company_address and company_address.fax %} - Fax: {{ company_address.fax }}{% endif %}
        </div>
        <div class="company-line">e-mail: {{ company_address.email_id if company_address and company_address.email_id else "" }}</div>
      </td>
      <td class="info-col-right">
        <div class="order-line"><span class="field-label">TECNICO:</span> {{ tecnico or "" }}</div>
        <div class="order-line">
          <span class="field-label">FECHA RECIBIDO:</span>
          {{ frappe.utils.formatdate(diagnostico.actual_start_date or diagnostico.creation, "dd/MM/yyyy") if diagnostico else "" }}
          &nbsp;&nbsp;{{ frappe.utils.format_time(diagnostico.actual_start_date or diagnostico.creation) if diagnostico else "" }}
        </div>
        <div class="order-line">
          <span class="field-label">FECHA DE CIERRE:</span>
          {{ frappe.utils.formatdate((work_order.actual_end_date if work_order else None) or (diagnostico.actual_end_date if diagnostico else None), "dd-MM-yyyy") }}
        </div>
      </td>
    </tr>
  </table>

  <!-- DATOS DEL CLIENTE Y EQUIPO -->
  <div class="box mt-6">
    <div class="box-header">Datos del cliente y equipo</div>
    <div class="box-body">
      <table class="info">
        <colgroup>
          <col style="width: 13%;"><col style="width: 20%;">
          <col style="width: 13%;"><col style="width: 20%;">
          <col style="width: 13%;"><col style="width: 21%;">
        </colgroup>
        <tr>
          <td class="field-label">CLIENTE:</td>
          <td>{{ doc.customer_name or doc.customer }}</td>
          <td></td>
          <td></td>
          <td class="field-label">NIT:</td>
          <td>{{ customer.tax_id if customer else "" }}</td>
        </tr>
        <tr>
          <td class="field-label">DIRECCION:</td>
          <td colspan="3">{{ customer_address.address_line1 if customer_address else "" }}</td>
          <td class="field-label">TEL:</td>
          <td>{{ customer_address.phone if customer_address and customer_address.phone else "" }}</td>
        </tr>
        <tr>
          <td class="field-label">MARCA Y AÑO:</td>
          <td>{{ equipo.brand if equipo else movimiento.marca_de_equipo if movimiento else "" }} {{ equipo.year if equipo else "" }}</td>
          <td class="field-label">MODELO:</td>
          <td>{{ equipo.model if equipo else movimiento.modelo if movimiento else "" }}</td>
          <td class="field-label">PLACA:</td>
          <td>{{ equipo.license_plate if equipo else movimiento.license_plate if movimiento else "" }}</td>
        </tr>
        <tr>
          <td class="field-label">EQUIPO A/C:</td>
          <td>REFRIGERACION:</td>
          <td class="field-label">KMS:</td>
          <td></td>
          <td class="field-label">COLOR:</td>
          <td>{{ equipo.color if equipo else movimiento.color if movimiento else "" }}</td>
        </tr>
        <tr>
          <td class="field-label">SERIE:</td>
          <td>{{ equipo.id or equipo.name if equipo else "" }}</td>
          <td class="field-label">HORAS IN:</td>
          <td>{{ diagnostico.next_service_reading if diagnostico and diagnostico.next_service_type == "Horas" else "" }}</td>
          <td class="field-label">OUT:</td>
          <td></td>
        </tr>
      </table>
    </div>
  </div>

  <!-- DIAGNOSTICO -->
  <table class="mt-6">
    <tr>
      <td style="width: 40%;">
        <div class="box">
          <div class="box-header">Diagnóstico</div>
          <div class="yellow-box">
            ID. {{ equipo_row.id_field if equipo_row and equipo_row.id_field else equipo.id if equipo else "" }}<br>
            AVISO No. {{ diagnostico.name if diagnostico else "" }}<br>
            HORAS MOTOR: {{ diagnostico.next_service_reading if diagnostico and diagnostico.next_service_type == "Horas" else "" }} HRS<br>
            PROX. SERVICIO: {{ diagnostico.next_service_reading if diagnostico else "" }} {{ "HRS" if diagnostico and diagnostico.next_service_type == "Horas" else "KMS" if diagnostico and diagnostico.next_service_type == "Kms" else "" }}<br>
            UNIDAD: {{ equipo.brand if equipo else "" }} / {{ equipo.model if equipo else "" }}
          </div>
        </div>
      </td>
      <td style="width: 60%;"></td>
    </tr>
  </table>

  <!-- REPUESTOS Y MATERIALES -->
  <div class="box mt-8 keep-together">
    <div class="box-header">Repuestos y materiales</div>
    <div class="box-body">
      <table class="items">
        <colgroup>
          <col style="width: 11%;"><col style="width: 13%;"><col style="width: 9%;">
          <col style="width: 34%;"><col style="width: 11%;"><col style="width: 11%;"><col style="width: 11%;">
        </colgroup>
        <tr>
          <th>REQUISICION</th>
          <th>CODIGO</th>
          <th>CANTIDAD</th>
          <th>DESCRIPCION</th>
          <th>PRECIO U.<br>CON IVA</th>
          <th>TOTAL SIN IVA</th>
          <th>TOTAL CON IVA</th>
        </tr>

        {% for item in doc.items %}
          {% set is_stock = frappe.db.get_value("Item", item.item_code, "is_stock_item") %}
          {% set has_bom = frappe.db.get_value("Item", item.item_code, "default_bom") %}
          {% if is_stock and not has_bom %}
            {% set amount_with_tax = (item.amount or 0) * (1 + tax_ratio) %}
            {% set unit_with_tax = (item.rate or 0) * (1 + tax_ratio) %}
            {% set ns.materials_without_tax = ns.materials_without_tax + (item.amount or 0) %}
            {% set ns.materials_with_tax = ns.materials_with_tax + amount_with_tax %}
            {% set ns.material_rows = ns.material_rows + 1 %}
            {% if item.discount_amount or item.discount_percentage %}
              {% set ns.discount_without_tax = ns.discount_without_tax + ((item.price_list_rate or item.rate or 0) * (item.qty or 0) - (item.amount or 0)) %}
              {% set ns.discount_with_tax = ns.discount_with_tax + (((item.price_list_rate or item.rate or 0) * (item.qty or 0) - (item.amount or 0)) * (1 + tax_ratio)) %}
            {% endif %}
            <tr class="{{ 'green-row' if item.discount_amount or item.discount_percentage else '' }}">
              <td class="field-label">{{ "REQUISICION" if ns.material_rows == 1 else "" }}</td>
              <td class="center bold">{{ item.item_code }}</td>
              <td class="right">{{ "%.2f"|format(item.qty or 0) }}</td>
              <td>{{ item.item_name or item.description or "" }}</td>
              <td class="right">{{ "%.2f"|format(unit_with_tax or 0) }}</td>
              <td class="right">{{ "%.2f"|format(item.amount or 0) }}</td>
              <td class="right">{{ "%.2f"|format(amount_with_tax or 0) }}</td>
            </tr>
          {% endif %}
        {% endfor %}

        {% if ns.material_rows == 0 %}
          <tr><td colspan="7" class="center">Sin repuestos</td></tr>
        {% endif %}

        <tr class="subtotal double-line">
          <td colspan="5" class="right">SUB TOTAL:</td>
          <td class="right">{{ "%.2f"|format(ns.materials_without_tax or 0) }}</td>
          <td class="right">{{ "%.2f"|format(ns.materials_with_tax or 0) }}</td>
        </tr>
      </table>
    </div>
  </div>

  <!-- SERVICIO -->
  <div class="box mt-8 keep-together">
    <div class="box-header">Servicio</div>
    <div class="box-body">
      <table class="items">
        <colgroup>
          <col style="width: 11%;"><col style="width: 13%;"><col style="width: 8%;"><col style="width: 6%;">
          <col style="width: 31%;"><col style="width: 11%;"><col style="width: 10%;"><col style="width: 10%;">
        </colgroup>
        <tr>
          <th>REQUISICION</th>
          <th>CODIGO</th>
          <th>CANTIDAD</th>
          <th>R&R</th>
          <th>DESCRIPCION</th>
          <th>PRECIO U.<br>CON IVA</th>
          <th>TOTAL SIN IVA</th>
          <th>TOTAL CON IVA</th>
        </tr>

        {% for item in doc.items %}
          {% set is_stock = frappe.db.get_value("Item", item.item_code, "is_stock_item") %}
          {% set has_bom = frappe.db.get_value("Item", item.item_code, "default_bom") %}
          {% if not is_stock and not has_bom %}
            {% set amount_with_tax = (item.amount or 0) * (1 + tax_ratio) %}
            {% set unit_with_tax = (item.rate or 0) * (1 + tax_ratio) %}
            {% set ns.services_without_tax = ns.services_without_tax + (item.amount or 0) %}
            {% set ns.services_with_tax = ns.services_with_tax + amount_with_tax %}
            {% set ns.service_rows = ns.service_rows + 1 %}
            <tr>
              <td class="field-label">{{ "REQUISICION" if ns.service_rows == 1 else "" }}</td>
              <td class="center bold">{{ item.item_code }}</td>
              <td class="right">{{ "%.2f"|format(item.qty or 0) }}</td>
              <td class="right">{{ item.get("custom_rr") or "" }}</td>
              <td>{{ item.description or item.item_name or "" }}</td>
              <td class="right">{{ "%.2f"|format(unit_with_tax or 0) }}</td>
              <td class="right">{{ "%.2f"|format(item.amount or 0) }}</td>
              <td class="right">{{ "%.2f"|format(amount_with_tax or 0) }}</td>
            </tr>
          {% endif %}
        {% endfor %}

        {% if ns.service_rows == 0 %}
          <tr><td colspan="8" class="center">Sin servicios</td></tr>
        {% endif %}

        <tr class="subtotal double-line">
          <td colspan="6" class="right">SUB TOTAL:</td>
          <td class="right">{{ "%.2f"|format(ns.services_without_tax or 0) }}</td>
          <td class="right">{{ "%.2f"|format(ns.services_with_tax or 0) }}</td>
        </tr>
      </table>
    </div>
  </div>

  {% set subtotal_without_tax = ns.materials_without_tax + ns.services_without_tax %}
  {% set subtotal_with_tax = ns.materials_with_tax + ns.services_with_tax %}

  <!-- TOTALES -->
  <table class="mt-8 keep-together">
    <tr>
      <td style="width: 54%;"></td>
      <td style="width: 46%;">
        <div class="box">
          <div class="box-header">Totales</div>
          <div class="box-body">
            <table class="totals">
              <colgroup><col style="width: 50%;"><col style="width: 25%;"><col style="width: 25%;"></colgroup>
              <tr>
                <td></td>
                <td class="right col-header">SIN IVA</td>
                <td class="right col-header">CON IVA</td>
              </tr>
              <tr>
                <td class="field-label">SUBTOTAL</td>
                <td class="right">{{ "%.2f"|format(subtotal_without_tax or 0) }}</td>
                <td class="right">{{ "%.2f"|format(subtotal_with_tax or 0) }}</td>
              </tr>
              {% if ns.discount_without_tax %}
              <tr>
                <td class="field-label">DESCUENTO REPUESTOS</td>
                <td class="right">{{ "%.2f"|format(ns.discount_without_tax or 0) }}</td>
                <td class="right">{{ "%.2f"|format(ns.discount_with_tax or 0) }}</td>
              </tr>
              {% endif %}
              <tr class="final-total">
                <td class="field-label">TOTAL A PAGAR</td>
                <td class="right">{{ "%.2f"|format(subtotal_without_tax or 0) }}</td>
                <td class="right grand-total">{{ "%.2f"|format(subtotal_with_tax or 0) }}</td>
              </tr>
            </table>
          </div>
        </div>
      </td>
    </tr>
  </table>

  <!-- FIRMAS -->
  <table class="firmas keep-together">
    <colgroup><col style="width: 46%;"><col style="width: 8%;"><col style="width: 46%;"></colgroup>
    <tr class="firma-space"><td>&nbsp;</td><td></td><td>&nbsp;</td></tr>
    <tr class="firma-border"><td></td><td></td><td></td></tr>
    <tr>
      <td class="firma-caption">
        Firma y sello del taller
        <div class="firma-sub">{{ company.company_name if company else "" }}</div>
      </td>
      <td></td>
      <td class="firma-caption">
        Recibí conforme
        <div class="firma-sub">Firma y nombre del cliente</div>
      </td>
    </tr>
  </table>

  <div class="note">
    NOTA: LOS REPUESTOS MARCADOS EN COLOR VERDE, SE LE APLICO EL DESCUENTO AUTORIZADO.
  </div>

</div>
